problem.brute_solution:
class Solution:
    def longest_continuous_span(self, prices: list[int], target_price: int) -> int:
        ans = 0
        for left in range(len(prices)):
            for right in range(left, len(prices)):
                if min(prices[left:right + 1]) <= target_price <= max(prices[left:right + 1]):
                    ans = max(ans, right - left + 1)
        return ans

