problem.optimal_solution:
class Solution:
    def longest_continuous_span(self, prices: list[int], target_price: int) -> int:
        if not prices:
            return 0
        n = len(prices)
        # 首先确认 target_price 是否存在
        left, right = 0, n - 1
        found = False
        while left <= right:
            mid = (left + right) // 2
            if prices[mid] == target_price:
                found = True
                break
            elif prices[mid] < target_price:
                left = mid + 1
            else:
                right = mid - 1
        if not found:
            return 0

        # 单调队列用于维护区间最大值和最小值
        max_queue = []  # 递减队列
        min_queue = []  # 递增队列
        right = 0
        ans = 0

        while right < n:
            # 维护 max_queue (递减)
            while max_queue and max_queue[-1] < prices[right]:
                max_queue.pop()
            max_queue.append(right)

            # 维护 min_queue (递增)
            while min_queue and min_queue[-1] > prices[right]:
                min_queue.pop()
            min_queue.append(right)

            # 移动 left 指针直到满足覆盖条件
            left = 0
            while True:
                min_val = prices[min_queue[0]]
                max_val = prices[max_queue[0]]
                if min_val <= target_price <= max_val:
                    ans = max(ans, right - left + 1)
                    break
                else:
                    left += 1
                    while max_queue and max_queue[0] < left:
                        max_queue.pop(0)
                    while min_queue and min_queue[0] < left:
                        min_queue.pop(0)
        return ans
